//! Ljung-Box `fitted_params` (D-06/DIAG-04), Jarque-Bera and Durbin-Watson
//! reference-fixture parity (Phase 17 plan 17-02).
//!
//! Fixture: `r_diagnostics/stationarity_portmanteau.json`
//! (`validation/reference/r/gen_diagnostics_reference.R`).
//!
//! `portmanteau_cases` pins `ljung_box(values, Some(lag), fitted_params)`
//! against R `Box.test(type = "Ljung-Box", fitdf = fitted_params)` for an
//! ARMA(1,1) residual series and first-differenced random-walk series. The
//! per-`series` `ljung_box_lag10_fitdf0`/`_fitdf2` blocks (generated by the
//! same R `Box.test` calls, carried over from 17-01's R diagnostics fixture)
//! additionally pin `fitted_params` 0 and 2 across every `r_diagnostics`
//! series. `jarque_bera` and `durbin_watson` pin this core crate's
//! implementations against the fixture's `jarque_bera` block (tseries
//! `jarque.bera.test`) and the closed-form Durbin-Watson added alongside
//! `portmanteau_cases`.

mod common;

use anofox_fcst_core::validation::{durbin_watson, jarque_bera, ljung_box};
use common::{assert_close, f64_vec, load_fixture, num, tolerance};

#[test]
fn ljung_box_matches_r_box_test_fitdf_for_portmanteau_cases() {
    let fx = load_fixture("r_diagnostics/stationarity_portmanteau.json");
    let statistic_abs = tolerance(&fx, "portmanteau_statistic_abs");
    let p_value_abs = tolerance(&fx, "portmanteau_p_value_abs");

    let cases = fx["portmanteau_cases"]
        .as_object()
        .expect("stationarity_portmanteau.json: 'portmanteau_cases' is not an object");
    assert_eq!(
        cases.len(),
        4,
        "expected 4 portmanteau cases in the fixture"
    );

    for (name, case) in cases {
        let values = f64_vec(&case["values"]);
        let lag = case["lag"].as_u64().unwrap() as usize;
        let fitdf = case["fitdf"].as_u64().unwrap() as usize;
        let want_statistic = num(&case["statistic"]);
        let want_df = case["df"].as_u64().unwrap() as usize;
        let want_p_value = num(&case["p_value"]);

        let got = ljung_box(&values, Some(lag), fitdf)
            .unwrap_or_else(|e| panic!("{name}: ljung_box returned Err: {e:?}"));

        assert_close(
            got.statistic,
            want_statistic,
            statistic_abs,
            0.0,
            &format!("{name} statistic"),
        );
        assert_eq!(got.df, want_df, "{name} df");
        assert_close(
            got.p_value,
            want_p_value,
            p_value_abs,
            0.0,
            &format!("{name} p_value"),
        );
    }
}

#[test]
fn ljung_box_matches_r_box_test_fitdf_for_every_r_diagnostics_series() {
    let fx = load_fixture("r_diagnostics/stationarity_portmanteau.json");
    let statistic_abs = tolerance(&fx, "statistic_abs");
    let p_value_abs = tolerance(&fx, "p_value_abs");

    let series = fx["series"]
        .as_object()
        .expect("stationarity_portmanteau.json: 'series' is not an object");

    for (name, block) in series {
        let values = f64_vec(&block["values"]);

        for (key, fitted_params) in [
            ("ljung_box_lag10_fitdf0", 0usize),
            ("ljung_box_lag10_fitdf2", 2usize),
        ] {
            let want = &block["tests"][key];
            let want_statistic = num(&want["statistic"]);
            let want_df = num(&want["df"]) as usize;
            let want_p_value = num(&want["p_value"]);

            let got = ljung_box(&values, Some(10), fitted_params)
                .unwrap_or_else(|e| panic!("{name}.{key}: ljung_box returned Err: {e:?}"));

            assert_close(
                got.statistic,
                want_statistic,
                statistic_abs,
                0.0,
                &format!("{name}.{key} statistic"),
            );
            assert_eq!(got.df, want_df, "{name}.{key} df");
            assert_close(
                got.p_value,
                want_p_value,
                p_value_abs,
                0.0,
                &format!("{name}.{key} p_value"),
            );
        }
    }
}

#[test]
